<script setup lang="ts">
type Company = { id:number; name:string; logo:string; operationalArea:string; nace:string; dangerClass:string; sgk:string; status:"active"|"passive" }
const props=defineProps<{ companies:Company[]; search?:string; statusFilter?:"all"|"active"|"passive" }>()
const filtered=computed(()=>{const t=(props.search||'').trim().toLocaleLowerCase('tr-TR');return props.companies.filter(x=>(!t||`${x.name} ${x.operationalArea} ${x.nace} ${x.dangerClass} ${x.sgk}`.toLocaleLowerCase('tr-TR').includes(t))&&(props.statusFilter==='all'||!props.statusFilter||x.status===props.statusFilter))})
</script>
<template><div class="overflow-hidden rounded-lg border border-gray-200 dark:border-gray-800"><table class="w-full text-left"><thead class="bg-gray-50"><tr><th class="px-4 py-3 text-xs text-gray-500">Firma</th><th class="px-4 py-3 text-xs text-gray-500">Operasyonel Alan</th><th class="px-4 py-3 text-xs text-gray-500">NACE</th><th class="px-4 py-3 text-xs text-gray-500">Tehlike</th><th class="px-4 py-3 text-xs text-gray-500">Durum</th></tr></thead><tbody class="divide-y divide-gray-100"><tr v-for="x in filtered" :key="x.id"><td class="px-4 py-4 text-sm font-semibold">{{x.name}}</td><td class="px-4 py-4 text-sm">{{x.operationalArea}}</td><td class="px-4 py-4 text-sm">{{x.nace}}</td><td class="px-4 py-4 text-sm">{{x.dangerClass}}</td><td class="px-4 py-4 text-sm">{{x.status==='active'?'Aktif':'Pasif'}}</td></tr></tbody></table></div></template>